const input = Array.isArray($json) ? $json : [$json];
return input.map((record) => {
  const months = Number(record.monthsOverdue ?? 0);
  const segment = months >= 6 ? 'high-priority-recall' : months >= 1 ? 'standard-recall' : 'not-overdue';
  const nextAction = record.contactAllowed ? `Send approved ${segment} message via ${record.preferredChannel ?? 'office channel'}.` : 'Do not contact.';
  return { json: { ...record, segment, nextAction } };
});
